med_countries = ["Algeria", "Egypt", "Morocco", "Tunisia", "Libya", "Syria", "Israel", "Lebanon", "Jordan", "Iraq", "Palestine", "Spain", "Portugal", "Italy", "Greece", "Cyprus", "Malta"]
med_country_features = []
for country in med_countries:
